1	import { sql } from 'drizzle-orm';
2	import { db } from './db';
3	
4	/**
5	 * Execute a handler with idempotency guarantees.
6	 * If the key has been seen before (within TTL), returns the cached response.
7	 * Otherwise executes the handler and caches the result.
8	 */
9	export async function withIdempotency<T>(
10	  key: string,
11	  handler: () => Promise<{ status: number; body: T }>,
12	  ttlMs: number = 24 * 60 * 60 * 1000, // 24 hours default
13	): Promise<{ status: number; body: T; cached: boolean }> {
14	  // Check for existing key
15	  const existing = await db.execute(
16	    sql`SELECT response_status, response_body FROM idempotency_keys
17	        WHERE key = ${key} AND expires_at > now()
18	        LIMIT 1`,
19	  );
20	
21	  if (existing.rows.length > 0) {
22	    const row = existing.rows[0] as Record<string, unknown>;
23	    return {
24	      status: (row.response_status as number) ?? 200,
25	      body: row.response_body as T,
26	      cached: true,
27	    };
28	  }
29	
30	  // Execute handler
31	  const result = await handler();
32	
33	  // Cache result
34	  const expiresAt = new Date(Date.now() + ttlMs);
35	  await db.execute(
36	    sql`INSERT INTO idempotency_keys (key, response_status, response_body, expires_at)
37	        VALUES (${key}, ${result.status}, ${JSON.stringify(result.body)}::jsonb, ${expiresAt.toISOString()}::timestamp)
38	        ON CONFLICT (key) DO NOTHING`,
39	  );
40	
41	  return { ...result, cached: false };
42	}
43	
44	/**
45	 * Extract idempotency key from request headers.
46	 * Returns undefined if no key is provided.
47	 */
48	export function getIdempotencyKey(headers: Headers): string | undefined {
49	  return (
50	    headers.get('x-idempotency-key') ??
51	    headers.get('idempotency-key') ??
52	    undefined
53	  );
54	}
